import { createRoute, z } from '@hono/zod-openapi'

type CommonRetriesType = { bulk: bigint; search: bigint }

const CommonRetriesSchema: z.ZodType<CommonRetriesType> = z
  .object({
    bulk: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The number of bulk operation retries.',
      }),
    search: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The number of search operation retries.',
      }),
  })
  .openapi({
    description: 'The retry statistics for bulk and search operations.',
    required: ['bulk', 'search'],
  })
  .openapi('CommonRetries')

type CommonUnitMillisType = bigint

const CommonUnitMillisSchema: z.ZodType<CommonUnitMillisType> = z
  .preprocess(
    (val) =>
      typeof val === 'number' && Number.isSafeInteger(val)
        ? BigInt(val)
        : typeof val === 'string' && /^-?\d+$/.test(val)
          ? BigInt(val)
          : val,
    z.int64(),
  )
  .openapi({ type: 'integer', format: 'int64', description: 'The time unit for milliseconds.' })
  .openapi('CommonUnitMillis')

type CommonDurationType = string

const CommonDurationSchema: z.ZodType<CommonDurationType> = z
  .string()
  .regex(/^(?:(-1)|([0-9\.]+)(?:d|h|m|s|ms|micros|nanos))$/)
  .openapi({
    description:
      'A duration. Units can be `nanos`, `micros`, `ms` (milliseconds), `s` (seconds), `m` (minutes), `h` (hours) and `d` (days). Also accepts `0` without a unit and `-1` to indicate an unspecified value.',
  })
  .openapi('CommonDuration')

const CommonBulkByScrollTaskStatusOrExceptionSchema: z.ZodType<CommonBulkByScrollTaskStatusOrExceptionType> =
  z
    .lazy(() =>
      z.xor([
        CommonBulkByScrollTaskStatusSchema.openapi({
          title: 'status',
          description: 'The status of the bulk by scroll task.',
        }),
        CommonErrorCauseSchema.openapi({
          title: 'exception',
          description: 'The error that occurred during the bulk by scroll task.',
        }),
      ]),
    )
    .openapi('CommonBulkByScrollTaskStatusOrException')

type CommonBulkByScrollTaskStatusType = {
  slice_id?: number
  total: bigint
  updated?: bigint
  created?: bigint
  deleted: bigint
  batches: number
  version_conflicts: bigint
  noops: bigint
  retries: z.infer<typeof CommonRetriesSchema>
  throttled_millis: z.infer<typeof CommonUnitMillisSchema>
  throttled?: z.infer<typeof CommonDurationSchema>
  requests_per_second: number
  canceled?: string
  throttled_until_millis: z.infer<typeof CommonUnitMillisSchema>
  throttled_until?: z.infer<typeof CommonDurationSchema>
  slices?: z.infer<typeof CommonBulkByScrollTaskStatusOrExceptionSchema>[]
}

const CommonBulkByScrollTaskStatusSchema: z.ZodType<CommonBulkByScrollTaskStatusType> = z
  .lazy(() =>
    z
      .object({
        slice_id: z.int32().exactOptional(),
        total: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The number of documents that were successfully processed.',
          }),
        updated: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .exactOptional()
          .openapi({
            type: 'integer',
            format: 'int64',
            description:
              'The number of documents that were successfully updated after the reindex operation.',
          }),
        created: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .exactOptional()
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The number of documents that were successfully created.',
          }),
        deleted: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The number of documents that were successfully deleted.',
          }),
        batches: z
          .int32()
          .openapi({
            description: 'The number of scroll responses pulled back by the reindex operation.',
          }),
        version_conflicts: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The number of version conflicts encountered by the reindex operation.',
          }),
        noops: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            description: 'The number of documents that were ignored.',
          }),
        retries: CommonRetriesSchema,
        throttled_millis: CommonUnitMillisSchema,
        throttled: CommonDurationSchema.exactOptional(),
        requests_per_second: z
          .float32()
          .openapi({
            description:
              'The number of requests per second effectively executed during the reindex operation.',
          }),
        canceled: z.string().exactOptional(),
        throttled_until_millis: CommonUnitMillisSchema.openapi({
          description: 'When the throttling will end in milliseconds.',
        }),
        throttled_until: CommonDurationSchema.exactOptional().openapi({
          description: 'The amount time before the throttling will end.',
        }),
        slices: z.array(CommonBulkByScrollTaskStatusOrExceptionSchema).exactOptional(),
      })
      .openapi({
        description: 'The status of a bulk by scroll task.',
        required: [
          'batches',
          'deleted',
          'noops',
          'requests_per_second',
          'retries',
          'throttled_millis',
          'throttled_until_millis',
          'total',
          'version_conflicts',
        ],
      }),
  )
  .openapi('CommonBulkByScrollTaskStatus')

const CommonErrorCauseSchema: z.ZodType<CommonErrorCauseType> = z
  .lazy(() =>
    z
      .object({
        type: z.string().openapi({ description: 'The type of error.' }),
        reason: z
          .string()
          .exactOptional()
          .openapi({ description: 'A human-readable explanation of the error, in English.' }),
        stack_trace: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The server stack trace, present only if the `error_trace=true` parameter was sent with the request.',
          }),
        caused_by: CommonErrorCauseSchema.exactOptional(),
        root_cause: z.array(CommonErrorCauseSchema).exactOptional(),
        suppressed: z.array(CommonErrorCauseSchema).exactOptional(),
        header: z.record(z.string(), CommonStringOrStringArraySchema).exactOptional(),
      })
      .catchall(
        z
          .any()
          .openapi({
            title: 'metadata',
            description: 'Any additional information about the error.',
          }),
      )
      .openapi({ required: ['type'] }),
  )
  .openapi('CommonErrorCause')

type CommonBulkByScrollTaskStatusOrExceptionType =
  | z.infer<typeof CommonBulkByScrollTaskStatusSchema>
  | z.infer<typeof CommonErrorCauseSchema>

