const CommonStringOrStringArraySchema = z
  .xor([z.string(), z.array(z.string())])
  .openapi('CommonStringOrStringArray')

type CommonErrorCauseType = {
  type: string
  reason?: string
  stack_trace?: string
  caused_by?: CommonErrorCauseType
  root_cause?: CommonErrorCauseType[]
  suppressed?: CommonErrorCauseType[]
  header?: { [key: string]: z.infer<typeof CommonStringOrStringArraySchema> }
}

type CommonFieldType = string

const CommonFieldSchema: z.ZodType<CommonFieldType> = z
  .string()
  .openapi({
    description:
      'The path to a field or an array of paths. Some APIs support wildcards in the path, which allows you to select multiple fields.',
  })
  .openapi('CommonField')

type CommonFieldsType = z.infer<typeof CommonFieldSchema> | z.infer<typeof CommonFieldSchema>[]

type CommonFieldValueType = boolean | ({ [key: string]: unknown } | null) | number | string

const CommonFieldValueSchema: z.ZodType<CommonFieldValueType> = z
  .union([z.boolean(), z.null().nullable(), z.number(), z.string()])
  .openapi({ description: 'A field value.' })
  .openapi('CommonFieldValue')

