const CommonAggregationsSingleBucketAggregateBaseSchema: z.ZodType<CommonAggregationsSingleBucketAggregateBaseType> =
  z
    .lazy(() =>
      (() => {
        const Schema = CommonAggregationsAggregateBaseSchema.and(
          z
            .object({
              doc_count: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64' }),
            })
            .openapi({ required: ['doc_count'] }),
        )
        return z
          .unknown()
          .check((ctx) => {
            const result = Schema.safeParse(ctx.value)
            if (!result.success) {
              for (const issue of result.error.issues) {
                if (issue.code === 'invalid_type') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'too_big') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'too_small') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'invalid_format') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'not_multiple_of') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'unrecognized_keys') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'invalid_union') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'invalid_key') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'invalid_element') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'invalid_value') {
                  ctx.issues.push({ ...issue, input: issue.input })
                } else if (issue.code === 'custom') {
                  ctx.issues.push({ ...issue, input: issue.input })
                }
              }
            }
            ;((ctx) => {
              const o = ctx.value
              if (typeof o !== 'object' || o === null || Array.isArray(o)) return
              const e = new Set()
              for (const k of ['doc_count']) {
                e.add(k)
              }
              const Schema = CommonAggregationsAggregateSchema.openapi({ title: 'aggregations' })
              for (const [k, val] of Object.entries(o)) {
                if (e.has(k)) {
                  continue
                }
                const result = Schema.safeParse(val)
                if (!result.success) {
                  for (const issue of result.error.issues) {
                    ctx.issues.push({ ...issue, path: [k, ...issue.path], input: issue.input })
                  }
                }
              }
            })(ctx)
          })
          .pipe(Schema)
      })(),
    )
    .openapi('CommonAggregationsSingleBucketAggregateBase')

