const IndicesCommonIndexingPressureMemorySchema = z
  .object({
    limit: z
      .xor([
        z.string(),
        z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({ type: 'integer', format: 'int64' }),
      ])
      .exactOptional()
      .openapi({
        description:
          'The number of outstanding bytes that may be consumed by indexing requests. When this limit is reached or exceeded,\nthe node will reject new coordinating and primary operations. When replica operations consume 1.5x this limit,\nthe node will reject new replica operations. Defaults to 10% of the heap.',
      }),
  })
  .openapi({ description: 'The memory-related settings for indexing backpressure.', required: [] })
  .openapi('IndicesCommonIndexingPressureMemory')

