const IngestCommonAttachmentProcessorSchema: z.ZodType<IngestCommonAttachmentProcessorType> = z
  .lazy(() =>
    IngestCommonProcessorBaseSchema.and(
      z
        .object({
          field: CommonFieldSchema,
          ignore_missing: z
            .boolean()
            .exactOptional()
            .openapi({
              description:
                'If `true` and field does not exist, the processor quietly exits without modifying the document.',
            }),
          indexed_chars: z
            .preprocess(
              (val) =>
                typeof val === 'number' && Number.isSafeInteger(val)
                  ? BigInt(val)
                  : typeof val === 'string' && /^-?\d+$/.test(val)
                    ? BigInt(val)
                    : val,
              z.int64(),
            )
            .exactOptional()
            .openapi({
              type: 'integer',
              format: 'int64',
              description:
                'The number of chars being used for extraction to prevent huge fields.\nUse `-1` for no limit.',
            }),
          indexed_chars_field: CommonFieldSchema.exactOptional(),
          properties: z
            .array(z.string())
            .exactOptional()
            .openapi({
              description:
                'Array of properties to select to be stored.\nCan be `content`, `title`, `name`, `author`, `keywords`, `date`, `content_type`, `content_length`, `language`.',
            }),
          target_field: CommonFieldSchema.exactOptional(),
          resource_name: z
            .string()
            .exactOptional()
            .openapi({
              description:
                'Field containing the name of the resource to decode.\nIf specified, the processor passes this resource name to the underlying Tika library to enable Resource Name Based Detection.',
            }),
        })
        .openapi({ required: ['field'] }),
    ),
  )
  .openapi('IngestCommonAttachmentProcessor')

