const IndicesCommonDataStreamSchema = z
  .object({
    _meta: CommonMetadataSchema.exactOptional(),
    allow_custom_routing: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'When `true`, the data stream allows custom routing on write request.',
      }),
    generation: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          "The current generation number for the data stream. This number acts as a cumulative count of the stream's rollovers, starting at 1.",
      }),
    hidden: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'When `true`, the data stream is hidden.' }),
    ilm_policy: CommonNameSchema.exactOptional(),
    next_generation_managed_by: IndicesCommonManagedBySchema.exactOptional(),
    prefer_ilm: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Indicates if ILM should take precedence over DSL in case both are configured to managed this data stream.',
      }),
    indices: z
      .array(IndicesCommonDataStreamIndexSchema)
      .openapi({
        description:
          "An array of objects containing information about the data stream's backing indexes.\nThe last item in this array contains information about the stream's current write index.",
      }),
    name: CommonDataStreamNameSchema,
    replicated: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When `true`, the data stream is created and managed by cross-cluster replication and the local cluster can not write into this data stream or change its mappings.',
      }),
    status: CommonHealthStatusSchema,
    system: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When `true`, the data stream is created and managed by an OpenSearch stack component and cannot be modified through normal user interaction.',
      }),
    template: CommonNameSchema,
    timestamp_field: IndicesCommonDataStreamTimestampFieldSchema,
  })
  .openapi({ required: ['generation', 'indices', 'name', 'status', 'template', 'timestamp_field'] })
  .openapi('IndicesCommonDataStream')

