const IndicesForcemergeQueryMaxNumSegmentsParamsSchema = z
  .preprocess((val) => {
    if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)) return val
    if (/^-?\d+$/.test(val)) return BigInt(val)
    const num = Number(val)
    return Number.isSafeInteger(num) ? BigInt(num) : val
  }, z.int64())
  .exactOptional()
  .openapi({
    param: {
      in: 'query',
      name: 'max_num_segments',
      description:
        'The number of larger segments into which smaller segments are merged.\nSet this parameter to 1 to merge all segments into one segment.\nThe default behavior is to perform the merge as necessary.',
      schema: { type: 'integer', format: 'int64' },
      style: 'form',
      required: false,
    },
  })

