const SnapshotCreateRequestBody = {
  content: {
    'application/json': {
      schema: z
        .object({
          ignore_unavailable: z
            .boolean()
            .exactOptional()
            .openapi({
              description:
                'When `true`, the request ignores any data streams and indexes that are missing or closed. \nWhen `false`, the request returns an error for any data streams or indexes that is missing or closed.',
            }),
          include_global_state: z
            .boolean()
            .default(true)
            .exactOptional()
            .openapi({
              description:
                'When `true`, includes the current cluster state in the snapshot. \nThe cluster state includes persistent cluster settings, composable index templates, legacy index templates, ingest pipelines, and ILM policies. \nThe cluster state also includes data stored in system indexes, such as watches and task records (configurable with `feature_states`).',
            }),
          indices: CommonIndicesSchema.exactOptional(),
          feature_states: z
            .array(z.string())
            .exactOptional()
            .openapi({
              description:
                'A list of feature states to include in the snapshot. Each feature state includes one or more system indexes which contain related data. You can view a list of features using the Get Feature API.  \nIf `include_global_state` is `true`, all current feature states are included by default. If `include_global_state` is `false`, no feature states are included by default.',
            }),
          metadata: CommonMetadataSchema.exactOptional(),
          partial: z
            .boolean()
            .default(false)
            .exactOptional()
            .openapi({
              description:
                'When `true`, enables the restoration of a partial snapshot from indexes with unavailable shards. \nOnly shards that were successfully included in the snapshot will be restored. All missing shards will be recreated as empty. \nWhen `false`, the entire restore operation will fail if one or more indexes included in the snapshot do not have all primary shards available.',
            }),
        })
        .openapi({ description: 'The snapshot definition.', required: [] }),
    },
  },
}

